from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PeerVNF(SchemaObject):
    peer_vnf = SchemaField(name="peerVnf")
    ip_address = SchemaField(name="ipAddress")
    status = SchemaField(name="status")

    def __init__(self, peer_vnf, ip_address, status):
        self.peer_vnf = peer_vnf
        self.ip_address = ip_address
        self.status = status
        super(PeerVNF, self).__init__()


class CuVnfDataAGENTV1(SchemaObject):
    redundancy_role = SchemaField(name="redundancyRole")
    activity_mode = SchemaField(name="activityMode")
    peer_vnf = SchemaField(name="peerVnf", klass=PeerVNF)

    def __init__(self, redundancy_role, activity_mode, peer_vnf):
        self.redundancy_role = redundancy_role
        self.activity_mode = activity_mode
        self.peer_vnf = peer_vnf

        super(CuVnfDataAGENTV1, self).__init__()
